import 'dart:math';

double meanAbsoluteDeviation(List<double> numbers) {
  if (numbers.isEmpty) return 0.0;

  double sum = 0.0;
  for (var num in numbers) {
    sum += num;
  }

  double mean = sum / numbers.length;

  double mads = 0.0;
  for (var num in numbers) {
    mads += abs(num - mean);
  }

  return mads / numbers.length;
}

