List<int> unique(List<int> l) {
  if (l.isEmpty) return [];
  int n = l.length;
  List<int> result = [];
  for (int i = 0; i < n; i++) {
    bool isDuplicate = false;
    for (int j = 0; j < i; j++) {
      if (l[i] == l[j]) {
        isDuplicate = true;
        break;
      }
    }
    if (!isDuplicate) {
      result.add(l[i]);
    }
  }
  return result;
}

