  List<String> result = [];
  int i = 0;
  while (i < s.length) {
    String currentChar = s[i];
    if (currentChar == ' ') {
      result.add(' ');
      i++;
    } else {
      // Find the next non-space character
      int j = i + 1;
      while (j < s.length && s[j] != ' ') {
        j++;
      }
      // Check if there are more characters after this block
      bool hasMoreCharsAfterBlock = j < s.length;
      // Get the substring from i to j (exclusive of j)
      String block = s.substring(i, j);
      // Determine the minimum length between the current block and a subsequent block
      int minLen = 0;
      if (hasMoreCharsAfterBlock) {
        // Find the next space after the current block
        int k = j + 1;
        while (k < s.length && s[k] != ' ') {
          k++;
        }
        // The next block starts at k
        int nextBlockSize = k - j;
        minLen = nextBlockSize;
      }
      // Determine the maximum number of characters we can take without exceeding the minLen
      int maxTake = math.min(block.length, minLen);
      // Take the last `maxTake` characters of the block
      String taken = block.substring(block.length - maxTake);
      result.add(taken);
      i = j; // Move past the processed block
    }
  }
  return result.join('');
}

