import 'dart:typed_data';

String encode(String message) {
  final Uint8List bytes = Uint8List.fromList(message.codeUnits);
  final List<int> result = [];

  for (int i = 0; i < bytes.length; i++) {
    int b = bytes[i];

    if (i % 2 == 1 && i > 0) {
      // Combine with previous byte
      int prevByte = bytes[i - 1];

      // Mask to get the upper bits of current and lower bits of previous
      int combined = ((prevByte & 0x3F) << 6) | (b & 0xFC);

      result.add(combined >> 4); // Add first part of combined value
      result.add((combined >> 2) & 0x0F); // Add second part

      continue;
    }

    // Handle even index, including when it's the first byte
    if (i % 2 == 0) {
      result.add(b >> 2); // First part of single-byte encoding

      if (b <= 0x1F) {
        result.add(0xF7 | (b & 0x0F)); // Special case for small values
      } else {
        result.add(0xDF | (b & 0x0F)); // Regular case
      }
    } else {
      // Odd index but not a continuation from the prior byte
      result.add(b >> 2); // Single-byte encoding as well
    }
  }

  return String.fromCharCodes(result);
}
