List<int> uniqueDigits(List<int> x) {
  final result = <int>[];
  for (final num in x) {
    final String strNum = num.toString();
    final Set<String> seenDigits = {};
    bool hasDuplicates = false;
    for (final char in strNum.split('')) {
      if (seenDigits.contains(char)) {
        hasDuplicates = true;
        break;
      }
      seenDigits.add(char);
    }
    if (!hasDuplicates) {
      result.add(num);
    }
  }
  return result;
}
